insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('parmentier-potiron-lentilles-vertes', 'Parmentier végétal aux lentilles et purée de potiron', 'Une couche de lentilles vertes mijotées aux carottes, oignon et thym, sous une purée de potiron et pommes de terre gratinée à l''emmental. Un parmentier d''automne sans viande, très rassasiant.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois en parts.', 4, 25, 55, array['plat', 'four', 'economique', 'batch-cooking']::text[]),
  ('spaghetti-thon-epinards-citron', 'Spaghetti au thon, épinards et citron', 'Des spaghetti enrobés d''une sauce minute au thon, à l''ail, aux épinards et au zeste de citron, avec un peu de parmesan. Prêt en 15 minutes avec des produits du placard.', 'Se garde 2 jours au réfrigérateur. Se réchauffe à la poêle avec un filet d''eau.', 2, 5, 15, array['plat', 'poele', 'economique']::text[]),
  ('farfalle-poulet-brocoli-parmesan', 'Farfalle au poulet, brocoli et parmesan', 'Des farfalle avec du poulet doré, des bouquets de brocoli et une sauce légère au fromage blanc, à l''ail et au parmesan. Le plat de pâtes qui coche toutes les cases.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 15, array['plat', 'poele']::text[]),
  ('poulet-endives-moutarde-riz', 'Poulet et endives poêlées à la moutarde, riz', 'Des endives coupées en quatre et caramélisées à la poêle, puis mijotées avec du poulet dans une sauce moutarde légère au fromage blanc, avec du riz. L''endive comme on ne la mange pas assez.', 'Se garde 2 jours au réfrigérateur. Réchauffer doucement sans faire bouillir la sauce.', 2, 10, 25, array['plat', 'poele']::text[]),
  ('dahl-potiron-lentilles-corail', 'Dahl de lentilles corail au potiron et épinards', 'Des lentilles corail fondues avec du potiron, des tomates, du gingembre et des épices douces, finies avec des épinards, et servies avec du riz basmati et un yaourt.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois.', 4, 15, 30, array['plat', 'mijote', 'economique', 'batch-cooking', 'monde']::text[]),
  ('veloute-patate-douce-pois-chiches-grilles', 'Velouté de patate douce et pois chiches grillés', 'Un velouté doux de patate douce, carotte et oignon au cumin, servi avec des pois chiches grillés au four, un yaourt et du pain. Une soupe-repas qui tient au corps.', 'Le velouté se garde 4 jours au réfrigérateur et se congèle ; les pois chiches se gardent à part dans une boîte.', 4, 15, 30, array['soupe', 'plat', 'economique', 'batch-cooking']::text[]),
  ('tajine-dinde-carottes-raisins-secs', 'Tajine de dinde aux carottes et raisins secs', 'Des morceaux de dinde mijotés avec des carottes, des oignons, des raisins secs, de la cannelle et du cumin, servis avec de la semoule et des amandes. Doux, sucré-salé et parfumé.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois.', 4, 20, 40, array['plat', 'mijote', 'batch-cooking', 'monde']::text[]),
  ('filet-porc-pommes-poelees-ecrase-carottes', 'Filet de porc aux pommes poêlées, écrasé de carottes', 'Des médaillons de filet de porc saisis, des quartiers de pomme caramélisés au thym et un écrasé de carottes et pommes de terre. L''association porc-pomme en version légère.', 'Se garde 2 jours au réfrigérateur.', 2, 15, 25, array['plat', 'poele']::text[]),
  ('cabillaud-poireaux-curry-riz', 'Cabillaud sur poireaux fondus au curry, riz basmati', 'Des dos de cabillaud pochés sur une fondue de poireaux au curry doux et à un trait de lait de coco, servis avec du riz basmati. Parfumé sans être lourd.', 'Se garde 2 jours au réfrigérateur. Réchauffer doucement à couvert.', 2, 15, 25, array['plat', 'poele', 'monde']::text[]),
  ('saumon-endives-braisees-pommes-de-terre', 'Saumon, endives braisées à l''orange et pommes de terre', 'Des endives braisées doucement au jus d''orange et au miel, un pavé de saumon poêlé et des pommes de terre vapeur. L''amertume des endives adoucie par l''orange.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 30, array['plat', 'poele']::text[]),
  ('boulettes-thon-sauce-tomate-spaghetti', 'Boulettes de thon à la sauce tomate, spaghetti', 'Des boulettes de thon, œuf, chapelure et parmesan dorées à la poêle puis mijotées dans une sauce tomate aux épinards, servies avec des spaghetti. Économique et adoré des enfants.', 'Les boulettes en sauce se gardent 3 jours au réfrigérateur.', 2, 20, 20, array['plat', 'poele', 'economique']::text[]),
  ('curry-tofu-patate-douce-epinards', 'Curry de tofu, patate douce et épinards', 'Des cubes de tofu dorés, de la patate douce et des épinards mijotés dans une sauce tomate au curry et au gingembre adoucie au yaourt, servis avec du riz basmati.', 'Se garde 3 jours au réfrigérateur.', 2, 15, 25, array['plat', 'mijote', 'monde']::text[]),
  ('quiche-legere-poireaux-thon', 'Quiche légère aux poireaux et au thon', 'Une quiche aux poireaux fondus et au thon, avec un appareil au lait et aux œufs sans crème, servie avec une grande salade de mâche. Plus légère que la version classique.', 'Se garde 3 jours au réfrigérateur. Se réchauffe au four ou se mange froide.', 4, 20, 40, array['plat', 'four', 'economique']::text[]),
  ('salade-lentilles-betterave-oeuf-mache', 'Salade de lentilles, betterave, œuf et mâche', 'Des lentilles vertes à la vinaigrette moutardée, des dés de betterave, un œuf mollet, de la mâche et quelques noix. Une salade-repas d''hiver, colorée et pleine de fibres.', 'Les lentilles assaisonnées se gardent 3 jours au réfrigérateur ; cuire les œufs au dernier moment.', 2, 15, 25, array['salade', 'plat', 'economique']::text[]),
  ('bowl-boulgour-pois-chiches-carottes-roties', 'Bowl de boulgour, pois chiches et carottes rôties', 'Des carottes et des pois chiches rôtis au cumin et au miel, sur du boulgour, avec de la mâche, de la feta et une sauce au yaourt citronnée. Un bol complet sans viande.', 'Se garde 3 jours au réfrigérateur, la mâche et la sauce à part.', 2, 15, 30, array['plat', 'four', 'economique']::text[]),
  ('blanquette-poulet-legere', 'Blanquette de poulet légère', 'Des morceaux de poulet pochés avec des carottes, des poireaux et des champignons, dans une sauce liée au fromage blanc et au citron plutôt qu''à la crème, servis avec du riz.', 'Se garde 4 jours au réfrigérateur. Réchauffer doucement sans faire bouillir.', 4, 20, 40, array['plat', 'mijote', 'batch-cooking']::text[]),
  ('gratin-pates-jambon-poireaux', 'Gratin de pâtes au jambon et aux poireaux', 'Des pâtes, des poireaux fondus et des dés de jambon dans une béchamel légère au lait, gratinés à l''emmental, avec une salade verte. Le gratin familial en version plus équilibrée.', 'Se garde 3 jours au réfrigérateur. Se réchauffe au four.', 4, 20, 30, array['plat', 'four', 'economique', 'batch-cooking']::text[]),
  ('dinde-pommes-curry-riz', 'Dinde au curry et aux pommes, riz basmati', 'Des lanières de dinde et des dés de pomme sautés avec un oignon et du curry doux, liés au yaourt, avec du riz basmati et des épinards. Une note sucrée-épicée de saison.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 20, array['plat', 'poele', 'monde']::text[]),
  ('oeufs-brouilles-champignons-epinards-tartines', 'Œufs brouillés aux champignons et épinards sur tartines', 'Des œufs brouillés crémeux avec des champignons poêlés et des épinards, servis sur des tartines de pain grillé. Un petit-déjeuner salé ou un brunch rapide.', 'À manger tout de suite.', 2, 5, 10, array['petit-dejeuner', 'poele']::text[]),
  ('bowl-yaourt-compote-pomme-avoine-noix', 'Bowl de yaourt, compote de pomme, avoine et noix', 'Du yaourt et du fromage blanc avec de la compote de pomme, des flocons d''avoine grillés à la cannelle, des dés de pomme et des noix. Sans cuisson ou presque, prêt en 5 minutes.', 'Se prépare la veille sans les flocons, qu''on ajoute au moment de servir.', 2, 5, 3, array['petit-dejeuner', 'economique']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

