insert into public.recipe_steps (recipe_id, position, instruction)
select r.id, v.pos, v.instruction
from (values
  ('parmentier-potiron-lentilles-vertes', 1, 'Cuire les lentilles 25 minutes dans une casserole d''eau non salée, puis les égoutter.'),
  ('parmentier-potiron-lentilles-vertes', 2, 'Éplucher le potiron et les pommes de terre, les couper en morceaux et les cuire 20 minutes dans une casserole d''eau bouillante salée.'),
  ('parmentier-potiron-lentilles-vertes', 3, 'Éplucher et émincer l''oignon et l''ail, et couper les carottes en petits dés.'),
  ('parmentier-potiron-lentilles-vertes', 4, 'Faire chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon et les carottes 8 minutes, puis l''ail, le concentré de tomate et le thym 1 minute.'),
  ('parmentier-potiron-lentilles-vertes', 5, 'Ajouter les lentilles avec un peu d''eau, saler, poivrer et laisser mijoter 5 minutes.'),
  ('parmentier-potiron-lentilles-vertes', 6, 'Préchauffer le four à 200 °C.'),
  ('parmentier-potiron-lentilles-vertes', 7, 'Égoutter le potiron et les pommes de terre et les écraser avec le lait chaud, la muscade et du sel.'),
  ('parmentier-potiron-lentilles-vertes', 8, 'Étaler les lentilles dans un plat, couvrir de purée, parsemer d''emmental et enfourner 20 minutes, jusqu''à ce que le dessus soit doré.'),
  ('parmentier-potiron-lentilles-vertes', 9, 'Servir avec la mâche.'),
  ('spaghetti-thon-epinards-citron', 1, 'Cuire les spaghetti dans une grande casserole d''eau bouillante salée selon le temps indiqué, puis les égoutter en gardant un peu d''eau de cuisson.'),
  ('spaghetti-thon-epinards-citron', 2, 'Faire chauffer l''huile dans une sauteuse à feu doux et cuire l''ail émincé et le piment 1 minute sans colorer.'),
  ('spaghetti-thon-epinards-citron', 3, 'Ajouter les épinards et mélanger jusqu''à ce qu''ils tombent.'),
  ('spaghetti-thon-epinards-citron', 4, 'Ajouter le thon égoutté et émietté, le zeste et le jus du citron, et réchauffer 1 minute.'),
  ('spaghetti-thon-epinards-citron', 5, 'Ajouter les spaghetti et un peu d''eau de cuisson, et mélanger jusqu''à ce que les pâtes soient bien enrobées.'),
  ('spaghetti-thon-epinards-citron', 6, 'Servir avec le parmesan râpé et du poivre.'),
  ('farfalle-poulet-brocoli-parmesan', 1, 'Cuire les farfalle dans une grande casserole d''eau bouillante salée selon le temps indiqué, en ajoutant le brocoli en petits bouquets pour les 5 dernières minutes. Égoutter en gardant un peu d''eau de cuisson.'),
  ('farfalle-poulet-brocoli-parmesan', 2, 'Couper le poulet en lanières.'),
  ('farfalle-poulet-brocoli-parmesan', 3, 'Faire chauffer l''huile dans une sauteuse à feu vif et dorer le poulet 6 minutes, jusqu''à ce qu''il soit cuit à cœur.'),
  ('farfalle-poulet-brocoli-parmesan', 4, 'Baisser le feu, ajouter l''ail émincé et cuire 1 minute.'),
  ('farfalle-poulet-brocoli-parmesan', 5, 'Hors du feu, ajouter les pâtes, le brocoli, le fromage blanc, la moitié du parmesan et un peu d''eau de cuisson, et mélanger.'),
  ('farfalle-poulet-brocoli-parmesan', 6, 'Servir avec le reste du parmesan et du poivre.'),
  ('poulet-endives-moutarde-riz', 1, 'Cuire le riz dans une casserole d''eau bouillante salée selon le temps indiqué, puis l''égoutter.'),
  ('poulet-endives-moutarde-riz', 2, 'Couper les endives en quatre dans la longueur et retirer le cœur amer.'),
  ('poulet-endives-moutarde-riz', 3, 'Faire chauffer la moitié de l''huile dans une sauteuse à feu vif et dorer les endives 5 minutes avec le miel, jusqu''à ce qu''elles caramélisent. Les réserver.'),
  ('poulet-endives-moutarde-riz', 4, 'Ajouter le reste de l''huile et dorer le poulet coupé en cubes 5 minutes.'),
  ('poulet-endives-moutarde-riz', 5, 'Remettre les endives avec l''eau, saler, couvrir et laisser mijoter 10 minutes à feu doux.'),
  ('poulet-endives-moutarde-riz', 6, 'Hors du feu, ajouter la moutarde et le fromage blanc, poivrer et mélanger.'),
  ('poulet-endives-moutarde-riz', 7, 'Servir avec le riz et le persil.'),
  ('dahl-potiron-lentilles-corail', 1, 'Éplucher le potiron et le couper en petits cubes. Éplucher et émincer l''oignon, l''ail et le gingembre.'),
  ('dahl-potiron-lentilles-corail', 2, 'Faire chauffer l''huile dans une cocotte à feu moyen et faire revenir l''oignon 5 minutes, puis l''ail, le gingembre, le curry et le curcuma 1 minute.'),
  ('dahl-potiron-lentilles-corail', 3, 'Ajouter les lentilles rincées, le potiron, les tomates et l''eau, saler et porter à ébullition.'),
  ('dahl-potiron-lentilles-corail', 4, 'Laisser mijoter 20 minutes à couvert en remuant de temps en temps : les lentilles doivent être fondues.'),
  ('dahl-potiron-lentilles-corail', 5, 'Cuire le riz 11 minutes dans une casserole d''eau bouillante salée, puis l''égoutter.'),
  ('dahl-potiron-lentilles-corail', 6, 'Ajouter les épinards au dahl et mélanger jusqu''à ce qu''ils tombent.'),
  ('dahl-potiron-lentilles-corail', 7, 'Servir avec le riz, un yaourt par personne et la coriandre.'),
  ('veloute-patate-douce-pois-chiches-grilles', 1, 'Préchauffer le four à 210 °C.'),
  ('veloute-patate-douce-pois-chiches-grilles', 2, 'Égoutter et sécher les pois chiches, puis les mélanger avec le paprika, la moitié de l''huile et du sel sur une plaque. Enfourner 25 minutes, jusqu''à ce qu''ils soient croustillants.'),
  ('veloute-patate-douce-pois-chiches-grilles', 3, 'Éplucher la patate douce, les carottes et l''oignon et les couper en morceaux.'),
  ('veloute-patate-douce-pois-chiches-grilles', 4, 'Faire chauffer le reste de l''huile dans une grande casserole et faire revenir l''oignon 5 minutes, puis le cumin 1 minute.'),
  ('veloute-patate-douce-pois-chiches-grilles', 5, 'Ajouter la patate douce, les carottes, l''eau et le bouillon émietté, et laisser mijoter 20 minutes : les légumes doivent être tendres.'),
  ('veloute-patate-douce-pois-chiches-grilles', 6, 'Mixer jusqu''à obtenir un velouté lisse.'),
  ('veloute-patate-douce-pois-chiches-grilles', 7, 'Servir avec une cuillerée de yaourt, les pois chiches grillés et le pain.'),
  ('tajine-dinde-carottes-raisins-secs', 1, 'Éplucher et émincer les oignons et le gingembre. Éplucher les carottes et les couper en bâtonnets.'),
  ('tajine-dinde-carottes-raisins-secs', 2, 'Couper la dinde en gros cubes.'),
  ('tajine-dinde-carottes-raisins-secs', 3, 'Faire chauffer l''huile dans une cocotte à feu vif et dorer la dinde 5 minutes. La réserver.'),
  ('tajine-dinde-carottes-raisins-secs', 4, 'Baisser le feu, ajouter les oignons et cuire 5 minutes, puis le gingembre, le cumin et la cannelle 1 minute.'),
  ('tajine-dinde-carottes-raisins-secs', 5, 'Ajouter les carottes, les raisins secs, le miel et l''eau, saler, couvrir et laisser mijoter 20 minutes.'),
  ('tajine-dinde-carottes-raisins-secs', 6, 'Ajouter la dinde et les pois chiches égouttés et poursuivre 10 minutes à couvert.'),
  ('tajine-dinde-carottes-raisins-secs', 7, 'Verser la semoule dans un saladier, la couvrir d''autant d''eau bouillante salée, couvrir 5 minutes puis l''égrener.'),
  ('tajine-dinde-carottes-raisins-secs', 8, 'Servir le tajine sur la semoule avec les amandes concassées et la coriandre.'),
  ('filet-porc-pommes-poelees-ecrase-carottes', 1, 'Éplucher les carottes et les pommes de terre, les couper en morceaux et les cuire 20 minutes dans une casserole d''eau bouillante salée.'),
  ('filet-porc-pommes-poelees-ecrase-carottes', 2, 'Couper le porc en médaillons épais, les pommes en quartiers et l''oignon en lamelles.'),
  ('filet-porc-pommes-poelees-ecrase-carottes', 3, 'Faire chauffer la moitié de l''huile dans une poêle à feu vif et saisir le porc 3 minutes de chaque côté. Le réserver.'),
  ('filet-porc-pommes-poelees-ecrase-carottes', 4, 'Ajouter le reste de l''huile, l''oignon, les pommes, le thym et le miel, et cuire 6 minutes : les pommes doivent être dorées mais encore fermes.'),
  ('filet-porc-pommes-poelees-ecrase-carottes', 5, 'Remettre le porc avec l''eau, couvrir et cuire 3 minutes à feu doux : il doit être cuit à cœur.'),
  ('filet-porc-pommes-poelees-ecrase-carottes', 6, 'Égoutter les légumes et les écraser à la fourchette avec le lait, du sel et du poivre.'),
  ('filet-porc-pommes-poelees-ecrase-carottes', 7, 'Servir le porc et les pommes avec l''écrasé.'),
  ('cabillaud-poireaux-curry-riz', 1, 'Cuire le riz 11 minutes dans une casserole d''eau bouillante salée, puis l''égoutter.'),
  ('cabillaud-poireaux-curry-riz', 2, 'Couper les poireaux en fines rondelles et les laver.'),
  ('cabillaud-poireaux-curry-riz', 3, 'Faire chauffer l''huile dans une sauteuse à feu doux et faire fondre les poireaux 10 minutes avec l''eau et du sel, à couvert.'),
  ('cabillaud-poireaux-curry-riz', 4, 'Ajouter le curry et le lait de coco et porter à frémissement.'),
  ('cabillaud-poireaux-curry-riz', 5, 'Poser le cabillaud sur les poireaux, saler, couvrir et cuire 8 minutes à feu doux : la chair doit s''effeuiller.'),
  ('cabillaud-poireaux-curry-riz', 6, 'Arroser de jus de citron vert et servir avec le riz et la coriandre.'),
  ('saumon-endives-braisees-pommes-de-terre', 1, 'Éplucher les pommes de terre et les cuire 25 minutes à la vapeur.'),
  ('saumon-endives-braisees-pommes-de-terre', 2, 'Couper les endives en deux dans la longueur et retirer le cœur amer.'),
  ('saumon-endives-braisees-pommes-de-terre', 3, 'Faire chauffer la moitié de l''huile dans une sauteuse à feu moyen et dorer les endives 4 minutes côté coupé.'),
  ('saumon-endives-braisees-pommes-de-terre', 4, 'Ajouter le jus de l''orange, le miel, l''eau et du sel, couvrir et braiser 15 minutes à feu doux : les endives doivent être fondantes.'),
  ('saumon-endives-braisees-pommes-de-terre', 5, 'Faire chauffer le reste de l''huile dans une poêle et cuire le saumon 4 minutes côté peau, puis 3 minutes de l''autre côté.'),
  ('saumon-endives-braisees-pommes-de-terre', 6, 'Servir le saumon avec les endives et leur jus, les pommes de terre, du poivre et la ciboulette.'),
  ('boulettes-thon-sauce-tomate-spaghetti', 1, 'Mélanger le thon égoutté et émietté avec l''œuf, la chapelure, la moitié du parmesan et du poivre, puis former des petites boulettes.'),
  ('boulettes-thon-sauce-tomate-spaghetti', 2, 'Faire chauffer l''huile dans une sauteuse à feu moyen et dorer les boulettes 5 minutes en les roulant délicatement. Les réserver.'),
  ('boulettes-thon-sauce-tomate-spaghetti', 3, 'Faire revenir l''ail émincé 1 minute, puis ajouter les tomates, le concentré et les herbes et laisser mijoter 10 minutes.'),
  ('boulettes-thon-sauce-tomate-spaghetti', 4, 'Ajouter les épinards et les boulettes, et cuire 4 minutes à couvert.'),
  ('boulettes-thon-sauce-tomate-spaghetti', 5, 'Cuire les spaghetti dans une grande casserole d''eau bouillante salée selon le temps indiqué, puis les égoutter.'),
  ('boulettes-thon-sauce-tomate-spaghetti', 6, 'Servir les spaghetti avec les boulettes et la sauce, le reste du parmesan et le basilic.'),
  ('curry-tofu-patate-douce-epinards', 1, 'Couper le tofu en cubes, l''éponger et le dorer 6 minutes dans la moitié de l''huile, à feu vif. Le réserver.'),
  ('curry-tofu-patate-douce-epinards', 2, 'Éplucher et émincer l''oignon, l''ail et le gingembre. Éplucher la patate douce et la couper en cubes.'),
  ('curry-tofu-patate-douce-epinards', 3, 'Faire chauffer le reste de l''huile dans la sauteuse à feu moyen et faire revenir l''oignon 5 minutes, puis l''ail, le gingembre et le curry 1 minute.'),
  ('curry-tofu-patate-douce-epinards', 4, 'Ajouter la patate douce et les tomates, saler, couvrir et laisser mijoter 15 minutes : la patate douce doit être tendre.'),
  ('curry-tofu-patate-douce-epinards', 5, 'Cuire le riz 11 minutes dans une casserole d''eau bouillante salée, puis l''égoutter.'),
  ('curry-tofu-patate-douce-epinards', 6, 'Ajouter le tofu et les épinards au curry, mélanger jusqu''à ce qu''ils tombent, puis incorporer le yaourt hors du feu.'),
  ('curry-tofu-patate-douce-epinards', 7, 'Servir avec le riz et la coriandre.'),
  ('quiche-legere-poireaux-thon', 1, 'Préchauffer le four à 190 °C.'),
  ('quiche-legere-poireaux-thon', 2, 'Couper les poireaux en fines rondelles, les laver et les faire fondre 10 minutes dans une sauteuse avec l''huile, à feu moyen.'),
  ('quiche-legere-poireaux-thon', 3, 'Dérouler la pâte dans un moule et la piquer à la fourchette.'),
  ('quiche-legere-poireaux-thon', 4, 'Battre les œufs avec le lait, la muscade, du sel et du poivre.'),
  ('quiche-legere-poireaux-thon', 5, 'Répartir les poireaux et le thon émietté sur la pâte, verser l''appareil et parsemer d''emmental.'),
  ('quiche-legere-poireaux-thon', 6, 'Enfourner 35 minutes : la quiche doit être dorée et prise au centre.'),
  ('quiche-legere-poireaux-thon', 7, 'Servir tiède avec la mâche assaisonnée au vinaigre.'),
  ('salade-lentilles-betterave-oeuf-mache', 1, 'Cuire les lentilles 25 minutes dans une casserole d''eau non salée, puis les égoutter.'),
  ('salade-lentilles-betterave-oeuf-mache', 2, 'Cuire les œufs 6 minutes dans l''eau bouillante, les refroidir dans l''eau froide et les écaler.'),
  ('salade-lentilles-betterave-oeuf-mache', 3, 'Couper la betterave en dés et ciseler l''échalote.'),
  ('salade-lentilles-betterave-oeuf-mache', 4, 'Fouetter la moutarde, le vinaigre, l''huile, du sel et du poivre, puis ajouter l''échalote.'),
  ('salade-lentilles-betterave-oeuf-mache', 5, 'Mélanger les lentilles tièdes avec la moitié de la vinaigrette.'),
  ('salade-lentilles-betterave-oeuf-mache', 6, 'Servir les lentilles sur la mâche avec la betterave, les œufs coupés en deux, les noix et le reste de vinaigrette.'),
  ('bowl-boulgour-pois-chiches-carottes-roties', 1, 'Préchauffer le four à 210 °C.'),
  ('bowl-boulgour-pois-chiches-carottes-roties', 2, 'Éplucher les carottes et les couper en bâtonnets. Égoutter et sécher les pois chiches.'),
  ('bowl-boulgour-pois-chiches-carottes-roties', 3, 'Mélanger les carottes et les pois chiches avec le cumin, le miel, l''huile et du sel sur une plaque, et enfourner 25 minutes.'),
  ('bowl-boulgour-pois-chiches-carottes-roties', 4, 'Verser le boulgour dans un saladier, le couvrir d''eau bouillante salée et laisser gonfler 15 minutes, puis l''égoutter.'),
  ('bowl-boulgour-pois-chiches-carottes-roties', 5, 'Mélanger les yaourts avec le jus de citron et du sel.'),
  ('bowl-boulgour-pois-chiches-carottes-roties', 6, 'Répartir le boulgour dans deux bols avec la mâche, les carottes, les pois chiches, la feta émiettée, la sauce et la menthe.'),
  ('blanquette-poulet-legere', 1, 'Couper le poulet en gros cubes. Éplucher les carottes et les couper en rondelles, couper le poireau en tronçons et le laver, émincer l''oignon.'),
  ('blanquette-poulet-legere', 2, 'Porter l''eau à ébullition dans une cocotte avec le bouillon, le laurier, le thym, l''oignon, les carottes et les poireaux, et laisser frémir 15 minutes.'),
  ('blanquette-poulet-legere', 3, 'Ajouter le poulet et les champignons émincés et laisser frémir 12 minutes : le poulet doit être cuit à cœur.'),
  ('blanquette-poulet-legere', 4, 'Cuire le riz dans une casserole d''eau bouillante salée selon le temps indiqué, puis l''égoutter.'),
  ('blanquette-poulet-legere', 5, 'Délayer la farine dans un peu de bouillon froid, la verser dans la cocotte et laisser épaissir 3 minutes en remuant.'),
  ('blanquette-poulet-legere', 6, 'Hors du feu, retirer le laurier, incorporer le fromage blanc et le jus de citron, saler et poivrer.'),
  ('blanquette-poulet-legere', 7, 'Servir avec le riz et le persil.'),
  ('gratin-pates-jambon-poireaux', 1, 'Préchauffer le four à 200 °C.'),
  ('gratin-pates-jambon-poireaux', 2, 'Cuire les pâtes 2 minutes de moins que le temps indiqué dans une grande casserole d''eau bouillante salée, puis les égoutter.'),
  ('gratin-pates-jambon-poireaux', 3, 'Couper les poireaux en rondelles, les laver et les faire fondre 10 minutes dans une sauteuse avec l''huile, à feu moyen.'),
  ('gratin-pates-jambon-poireaux', 4, 'Saupoudrer de farine, mélanger 1 minute, puis verser le lait en fouettant et laisser épaissir 4 minutes. Ajouter la muscade, du sel et du poivre.'),
  ('gratin-pates-jambon-poireaux', 5, 'Mélanger les pâtes, la sauce aux poireaux et le jambon coupé en dés dans un plat.'),
  ('gratin-pates-jambon-poireaux', 6, 'Parsemer d''emmental et enfourner 15 minutes, jusqu''à ce que le dessus soit doré.'),
  ('gratin-pates-jambon-poireaux', 7, 'Servir avec la salade assaisonnée au vinaigre.'),
  ('dinde-pommes-curry-riz', 1, 'Cuire le riz 11 minutes dans une casserole d''eau bouillante salée, puis l''égoutter.'),
  ('dinde-pommes-curry-riz', 2, 'Couper la dinde en lanières, la pomme en dés et émincer l''oignon.'),
  ('dinde-pommes-curry-riz', 3, 'Faire chauffer l''huile dans une sauteuse à feu vif et dorer la dinde 4 minutes. La réserver.'),
  ('dinde-pommes-curry-riz', 4, 'Faire revenir l''oignon 4 minutes, puis la pomme et le curry 2 minutes.'),
  ('dinde-pommes-curry-riz', 5, 'Remettre la dinde avec l''eau, saler et cuire 3 minutes : elle doit être cuite à cœur.'),
  ('dinde-pommes-curry-riz', 6, 'Ajouter les épinards et mélanger jusqu''à ce qu''ils tombent, puis, hors du feu, incorporer le yaourt.'),
  ('dinde-pommes-curry-riz', 7, 'Servir avec le riz et la coriandre.'),
  ('oeufs-brouilles-champignons-epinards-tartines', 1, 'Émincer les champignons et les faire dorer 5 minutes dans l''huile, à feu vif.'),
  ('oeufs-brouilles-champignons-epinards-tartines', 2, 'Ajouter les épinards et mélanger jusqu''à ce qu''ils tombent.'),
  ('oeufs-brouilles-champignons-epinards-tartines', 3, 'Battre les œufs avec le fromage blanc, du sel et du poivre, et les verser dans la poêle à feu doux.'),
  ('oeufs-brouilles-champignons-epinards-tartines', 4, 'Remuer sans cesse 3 minutes, jusqu''à ce que les œufs soient pris mais encore crémeux.'),
  ('oeufs-brouilles-champignons-epinards-tartines', 5, 'Faire griller le pain et le garnir d''œufs brouillés et de ciboulette.'),
  ('bowl-yaourt-compote-pomme-avoine-noix', 1, 'Faire griller les flocons d''avoine 3 minutes à sec dans une poêle avec la cannelle, en remuant.'),
  ('bowl-yaourt-compote-pomme-avoine-noix', 2, 'Couper les pommes en petits dés.'),
  ('bowl-yaourt-compote-pomme-avoine-noix', 3, 'Mélanger les yaourts et le fromage blanc et les répartir dans deux bols.'),
  ('bowl-yaourt-compote-pomme-avoine-noix', 4, 'Ajouter la compote, les pommes, les flocons et les noix concassées.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('parmentier-potiron-lentilles-vertes', 'spaghetti-thon-epinards-citron', 'farfalle-poulet-brocoli-parmesan', 'poulet-endives-moutarde-riz', 'dahl-potiron-lentilles-corail', 'veloute-patate-douce-pois-chiches-grilles', 'tajine-dinde-carottes-raisins-secs', 'filet-porc-pommes-poelees-ecrase-carottes', 'cabillaud-poireaux-curry-riz', 'saumon-endives-braisees-pommes-de-terre', 'boulettes-thon-sauce-tomate-spaghetti', 'curry-tofu-patate-douce-epinards', 'quiche-legere-poireaux-thon', 'salade-lentilles-betterave-oeuf-mache', 'bowl-boulgour-pois-chiches-carottes-roties', 'blanquette-poulet-legere', 'gratin-pates-jambon-poireaux', 'dinde-pommes-curry-riz', 'oeufs-brouilles-champignons-epinards-tartines', 'bowl-yaourt-compote-pomme-avoine-noix')) <> 234 then
    raise exception 'Lignes d''ingrédients manquantes dans le onzième lot de recettes.';
  end if;
end;
$$;
